<?php $pageTitle='Audit logs';$actors=[];$actions=[];foreach($logs as $log){$actors[$log['username']??'System']=true;$actions[$log['action']]=true;} ?>
<div class="gov-page audit-page gov-enter"><section class="audit-hero"><div class="gov-brand"><img src="<?= e(url('assets/images/gbu-emblem.png')) ?>" alt="" width="44" height="44"><span>Gautam Buddha University<br><b>Governance and traceability</b></span></div><h1>Audit history</h1><p>Review the latest 250 application mutations with actor, entity, network origin, and timestamp.</p><div class="audit-summary"><span><b><?= count($logs) ?></b> events loaded</span><span><b><?= count($actors) ?></b> recorded actors</span><span><b><?= count($actions) ?></b> action types</span></div></section><section class="audit-controls"><label class="gov-search"><span class="gov-icon icon-search" aria-hidden="true"></span><input id="audit-search" type="search" placeholder="Search action, actor, entity, or IP" aria-label="Search audit history"></label><button id="audit-expand" type="button"><span class="gov-icon icon-detail" aria-hidden="true"></span>Show technical details</button></section><?php if($logs):?><section class="audit-timeline" aria-live="polite"><?php foreach($logs as $i=>$log):$parts=explode('.',$log['action'],2);?><article data-audit-row data-search="<?= e(strtolower(implode(' ',[$log['username']??'System',$log['action'],$log['entity_type'],$log['entity_id'],$log['ip_address']]))) ?>" style="--gov-order:<?= $i ?>"><time><strong><?= e(date('d M Y',strtotime($log['created_at']))) ?></strong><span><?= e(date('H:i:s',strtotime($log['created_at']))) ?></span></time><span class="audit-event-icon gov-icon icon-audit" aria-hidden="true"></span><div class="audit-event"><span><?= e(ucfirst(str_replace('_',' ',$parts[0]))) ?></span><h2><?= e(ucwords(str_replace(['_','.'],' ',$log['action']))) ?></h2><p>Performed by <strong><?= e($log['username']??'System') ?></strong></p></div><div class="audit-entity"><span>Entity</span><strong><?= e(ucwords(str_replace('_',' ',$log['entity_type']))) ?></strong><small>Record <?= e((string)$log['entity_id']) ?></small></div><div class="audit-technical"><span>IP address</span><code><?= e($log['ip_address']?:'Not recorded') ?></code></div></article><?php endforeach;?><div class="gov-filter-empty" hidden><strong>No matching audit events</strong><span>Try a different search term.</span></div></section><?php else:?><section class="gov-empty"><span class="gov-icon icon-audit" aria-hidden="true"></span><h2>No audit events</h2><p>Recorded system changes will appear here.</p></section><?php endif;?></div>
<script>(()=>{const search=document.getElementById('audit-search'),rows=[...document.querySelectorAll('[data-audit-row]')],empty=document.querySelector('.gov-filter-empty'),expand=document.getElementById('audit-expand');search?.addEventListener('input',()=>{const term=search.value.trim().toLowerCase();let shown=0;rows.forEach(row=>{const visible=row.dataset.search.includes(term);row.hidden=!visible;if(visible)shown++;});if(empty)empty.hidden=shown!==0;});expand?.addEventListener('click',()=>{const active=document.body.classList.toggle('audit-details-visible');expand.textContent=active?'Hide technical details':'Show technical details';});})();</script>
